#!/usr/bin/env bash
# Headless end-to-end test: the binary talks to an LD_PRELOAD fake hidraw
# device (mock_hidraw.so) through a synthetic sysfs tree. No physical
# mouse is involved; the mock's sector contents start from the golden
# format-7 sectors generated by gen_golden.py.
set -euo pipefail

cd "$(dirname "$0")"
BIN=./ratslap-g305x
MOCK="$PWD/mock_hidraw.so"

TMP="$(mktemp -d "${TMPDIR:-/tmp}/rslap-it.XXXXXX")"
trap 'rm -rf "$TMP"' EXIT

SYS="$TMP/sys"
DEV="$TMP/dev"
mkdir -p "$SYS/hidraw0/device" "$SYS/hidraw1/device" "$DEV"

# hidraw0: the G305 X itself, as the kernel exposes a hid-logitech-dj child
# (owner-confirmed wpid 046d:40bb behind a 046d:c547 receiver).
printf 'HID_ID=0003:0000046D:000040BB\nHID_NAME=Logitech G305 X\nDRIVER=logitech-hidpp-device\n' \
    > "$SYS/hidraw0/device/uevent"
# hidraw1: the LIGHTSPEED receiver — scan expands it to 6 strict slots; the
# mock answers those with HID++ 1.0 errors, like an empty receiver slot.
printf 'HID_ID=0003:0000046D:0000C547\nHID_NAME=Logitech USB Receiver\nDRIVER=logitech-dj\n' \
    > "$SYS/hidraw1/device/uevent"
# minimal report descriptor: vendor page + report ID 0x11 (the HID++ check)
DESC='\x06\x00\xff\x09\x01\xa1\x01\x85\x11\x75\x08\x95\x13\x09\x02\xb1\x02\xc0'
printf "$DESC" > "$SYS/hidraw0/device/report_descriptor"
printf "$DESC" > "$SYS/hidraw1/device/report_descriptor"

export RSLAP_SYSFS_PATH="$SYS"
export RSLAP_DEV_PREFIX="$DEV"
export RSLAP_STATE_DIR="$TMP/state"
export HOME="$TMP"
export LD_PRELOAD="$MOCK"
export MOCK_MOUSE_NODE=hidraw0
export MOCK_STATE="$TMP/mock-state.bin"

failures=0
ok()   { echo "  ok: $1"; }
bad()  { echo "  FAIL: $1"; failures=$((failures + 1)); }
check() { # description, command...
    local desc="$1"; shift
    if "$@" > "$TMP/out" 2> "$TMP/err"; then ok "$desc"; else bad "$desc (exit $?)"; fi
}
check_grep() { # description, pattern, command... (command must succeed)
    local desc="$1" pat="$2"; shift 2
    if "$@" > "$TMP/out" 2> "$TMP/err" && grep -q "$pat" "$TMP/out" "$TMP/err"; then
        ok "$desc"
    else
        bad "$desc"
        sed 's/^/    | /' "$TMP/out" "$TMP/err" | head -12
    fi
}
check_grep_any() { # description, pattern, command... (exit code ignored)
    local desc="$1" pat="$2"; shift 2
    set +e
    "$@" > "$TMP/out" 2> "$TMP/err"
    set -e
    if grep -q "$pat" "$TMP/out" "$TMP/err"; then
        ok "$desc"
    else
        bad "$desc"
        sed 's/^/    | /' "$TMP/out" "$TMP/err" | head -12
    fi
}
check_exit() { # expected-code, description, command...
    local want="$1" desc="$2"; shift 2
    set +e
    "$@" > "$TMP/out" 2> "$TMP/err"
    local got=$?
    set -e
    if [ "$got" -eq "$want" ]; then ok "$desc (exit $got)"; else bad "$desc: want exit $want, got $got"; fi
}

echo "== list"
check_grep "list finds the mouse with its exact VID:PID" \
    'Logitech G305 X  \[wireless, 046d:40bb, .*/dev/hidraw0\]' $BIN list

echo "== info"
check_grep "info shows format 7" "profile format 7" $BIN info
check_grep "info shows battery" "battery: 85% Discharging" $BIN info
check_grep "info shows the golden profile" "Profile 1" $BIN info
check_grep "info shows G6 = DPI Shift" "G6=DPI Shift" $BIN info
check_grep "info shows the ROM default" "Default — ROM default" $BIN info
check_grep "no-arg run prints the active profile" "report rate: 1000 Hz" $BIN

echo "== safety gate"
check_exit 4 "button refused without backup and --yes" $BIN button 4 media:next
check_grep_any "refusal explains itself" "without a backup" $BIN button 4 media:next

echo "== backup"
check_grep "backup saves sectors" "saved .* sectors" $BIN backup "$TMP/mem.txt"
check_grep "backup records vid_pid" "vid_pid 046d:40bb" cat "$TMP/mem.txt"
check_grep "backup contains the directory sector" "sector 0x0000" cat "$TMP/mem.txt"
check_grep "backup contains profile sector 1" "sector 0x0001" cat "$TMP/mem.txt"

echo "== writes (gate now satisfied by the backup)"
check_grep "button write goes through and verifies" "written to slot 1 (verified)" \
    $BIN button 4 media:next
check_grep "re-read shows the new binding" "G4=Next Track" $BIN info
check_grep "key combo binding" "Ctrl+Shift+F13" $BIN button 6 ctrl+shift+f13 --yes
check_grep "gbutton writes the G-shift region" "written to slot 1" $BIN gbutton 1 right --yes
check_grep "G-shift G1 now right click" "G1=Right Click" $BIN info
check_grep "dpi edit" "DPI level 3 -> 1600 x 1600" $BIN dpi 3 1600 --yes
check_grep "dpi snapping to the supported list" "snapped 2333 to the nearest supported value 1600" \
    $BIN dpi 4 2333 --yes
check_grep "rate edit" "report rate 500 Hz written" $BIN rate 500 --yes
check_grep "live dpi preview survives the on-board/host mode quirk" \
    "live DPI now 1600" $BIN dpi --live 1600
check_grep "activate slot 2" "active profile: slot 2" $BIN activate 2
check_grep "info marks slot 2 active" "slot 2 (active)" $BIN info
check_grep "activate slot 1 back (hop path)" "active profile: slot 1" $BIN activate 1

echo "== factory-fresh device (blank user directory, ROM active)"
FRESH="$TMP/fresh.bin"
check_grep "activate creates the directory entry and selects slot 1" \
    "active profile: slot 1" env MOCK_STATE="$FRESH" MOCK_BLANK_DIR=1 MOCK_ROM_ACTIVE=1 \
    $BIN activate 1
check_grep "fresh device: slot 1 is active, not unused" "slot 1 (active)" \
    env MOCK_STATE="$FRESH" $BIN info
check_grep "fresh device: other slots still unused" "unused slot 2" \
    env MOCK_STATE="$FRESH" $BIN info
check_grep "second activate appends another directory entry" \
    "active profile: slot 3" env MOCK_STATE="$FRESH" $BIN activate 3

echo "== reset (factory ROM copy)"
check_grep "reset copies ROM over the active slot" "reset to the factory profile" \
    $BIN reset --yes
check_grep "reset profile has ROM bindings" "G6=DPI Cycle" $BIN info

echo "== restore"
check_grep "restore without --yes is allowed after a backup" "restored .* sector" \
    $BIN restore "$TMP/mem.txt"
check_grep "restored profile is back" "G6=DPI Shift" $BIN info
check_grep "restore undid the G4 edit (backup predates it)" "G4=Back" $BIN info

echo "== restore refuses mismatched device headers"
sed 's/vid_pid 046d:40bb/vid_pid 046d:4074/' "$TMP/mem.txt" > "$TMP/other.txt"
check_exit 2 "restore refuses a backup from another device" $BIN restore "$TMP/other.txt" --yes

echo "== usage errors"
check_exit 3 "unknown command" $BIN frobnicate
check_exit 3 "button number out of range" $BIN button 9 left --yes
check_exit 3 "bad rate" $BIN rate 123 --yes

echo "== keylist"
check_grep "--listkeys lists media keys" "media:playpause" $BIN --listkeys
check_grep "--listkeys lists functions" "dpicycle" $BIN --listkeys
check_grep "--listkeys lists disable" "disable" $BIN --listkeys

echo "== no device present"
RSLAP_SYSFS_PATH="$TMP/empty" check_grep_any "empty sysfs: clean no-device exit" \
    "no compatible device found" $BIN list
RSLAP_SYSFS_PATH="$TMP/empty" check_exit 1 "list without a device exits 1" $BIN list

echo
if [ "$failures" -gt 0 ]; then
    echo "integration: $failures check(s) FAILED"
    exit 1
fi
echo "integration: all checks passed"
